          "oneOf": [
            {
              "type": "string",
              "pattern": "^([0-9]+(ns|us|µs|ms|s|m|h))+$"
            },
            {
              "type": "integer"
            }
          ],
          "default": "30s"
        },
        "authentication": {
              "type": "string"
            },
            "bucket": {
              "type": "string"
            },
            "prefix": {
              "type": "string"
            },
            "endpoint": {
              "type": "string"
            },
            "poll_interval": {
              "oneOf": [
                {
                  "type": "string",
                  "pattern": "^([0-9]+(ns|us|µs|ms|s|m|h))+$"
                },
                {
                  "type": "integer"
                }
              ],

	}
	s := StoreSnapshot{
		ns: map[string]*namespace{
			defaultNs: newNamespace("default", "Default", now),
		},
		evalDists: map[string][]*storage.EvaluationDistribution{},
		now:       now,
	}

	for i, fi := range files {
		if err := func() error {
			defer fi.Close()

			stat, err := fi.Stat()
			if err != nil {
				return err
			}

			buf := &bytes.Buffer{}
			reader := io.TeeReader(fi, buf)

			if err := validator.Validate(stat.Name(), reader); err != nil {
				return err
			}

			decoder := yaml.NewDecoder(buf)
			// Support YAML stream by looping until we reach an EOF.
			for {
				doc := new(ext.Document)

				if err := decoder.Decode(doc); err != nil {
					if errors.Is(err, io.EOF) {
						break
					}
					return err
				}

				// OCI layers identify their namespace in a descriptor annotation.
				if annotated, ok := fi.(interface{ Namespace() string }); ok && annotated.Namespace() != "" {
					doc.Namespace = annotated.Namespace()
				}
				if doc.Namespace == "" {
					doc.Namespace = "default"
				}

				if err := s.addDoc(doc); err != nil {
					return err
				}
			}

			return nil
		}(); err != nil {
			for _, pending := range files[i+1:] {
				pending.Close()
			}
			return nil, err
		}
	}


	if err := ctx.Err(); err != nil {
		for _, file := range response.Files {
			file.Close()
		}
		return nil, "", err
	}
	snapshot, err := storagefs.SnapshotFromFiles(response.Files...)
	if err != nil {
		s.logger.Error("failed building OCI snapshot", zap.Error(err))
		return nil, "", err
	}

	s.snapshot = snapshot
	s.digest = response.Digest
	s.logger.Debug("updated OCI snapshot", zap.String("digest", s.digest.String()))
	return snapshot, s.digest, nil
}

